CustomField.formula:
/*First if completed same day*/
if( DateValue(LastModifiedDate)=TODAY(), 
/*Adjusts Closed Hour/Minute if it's before or after hours*/
	if(Current_Work_Hour__c<8, 8, if(Current_Work_Hour__c>20, 20, Current_Work_Hour__c))+
	if(Current_Work_Hour__c<8 || Current_Work_Hour__c>20, 0, Minute(TimeValue(NOW()))/60)
	- 
/*Adjust Created Hour/Minute if it's before or after hours*/
	(if(Last_Modified_Hour__c<8, 8, if(Last_Modified_Hour__c>20, 20, Last_Modified_Hour__c))+
	if(Last_Modified_Hour__c<8 || Last_Modified_Hour__c>20,0, Minute(TimeValue(LastModifiedDate)))/60),



/*If not the same day, calcs hours of first day, if after hours or weekend rounds Created down and Completed up*/
	if( Weekday(DateValue(LastModifiedDate))=7 || Weekday(DateValue(LastModifiedDate))=0 ||  Last_Modified_Hour__c>=20, 0, 
/*If it's before hours, limit to 8 hours*/
	if(Last_Modified_Hour__c<8, 8, 20-(Last_Modified_Hour__c))+
	if(Last_Modified_Hour__c<8 || Last_Modified_Hour__c>20, 0, (Minute(TimeValue(LastModifiedDate))/60))
    )
    +
/*Calcs days between and converts to hours by multiplying by 8 workhours*/
	(CASE( WEEKDAY(DateValue(LastModifiedDate)),
/*This excludes End Dates e.g. Mon Tuesday Wednesday = 1*/
1 , CASE( MOD( Today()-DateValue(LastModifiedDate),7),1,0,2,1,3,2,4,3,5,4,6,5,0),
2 , CASE( MOD( Today()-DateValue(LastModifiedDate),7),1,0,2,1,3,2,4,3,5,3,6,3,0),
3 , CASE( MOD( Today()-DateValue(LastModifiedDate),7),1,0,2,1,3,2,4,2,5,2,6,3,0),
4 , CASE( MOD( Today()-DateValue(LastModifiedDate),7),1,0,2,1,3,1,4,1,5,2,6,3,0),
5 , CASE( MOD( Today()-DateValue(LastModifiedDate),7),1,0,2,0,3,0,4,1,5,2,6,2,0),
6 , CASE( MOD( Today()-DateValue(LastModifiedDate),7),1,0,2,0,3,0,4,1,5,2,6,3,0),
7 , CASE( MOD( Today()-DateValue(LastModifiedDate),7),1,0,2,0,3,0,4,1,5,2,6,2,0),
999)
+
(FLOOR(( Today()-DateValue(LastModifiedDate) )/7)*5))*8
	+
/*Calcs days at the end*/
/*If it's before hours, limit to 8 hours*/
	if(Current_Work_Hour__c<8, 0, if(Current_Work_Hour__c>20, 20, Current_Work_Hour__c-8))+
	if(Current_Work_Hour__c<8 || Current_Work_Hour__c>20, 0, (Minute(TimeValue(NOW()))/60))

)
